import {addUsage} from './turnUsage.js';

// specs/hal-engine-config-hooks/spec.md#14
it('adds each reported token field without changing either round', () => {
  const earlier = {inputTokens: 11, outputTokens: 2, totalTokens: 17};
  const later = {inputTokens: 23, outputTokens: 3, totalTokens: 31};

  expect(addUsage(earlier, later)).toEqual({inputTokens: 34, outputTokens: 5, totalTokens: 48});
  expect(earlier).toEqual({inputTokens: 11, outputTokens: 2, totalTokens: 17});
  expect(later).toEqual({inputTokens: 23, outputTokens: 3, totalTokens: 31});
});
EOF
